#include <stdio.h>
#include <stdlib.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    int *a = (int*)malloc((n + 1) * sizeof(int));
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    int val, pos; scanf("%d %d", &val, &pos);
    for (int i = n; i > pos; i--) a[i] = a[i - 1];
    a[pos] = val;
    for (int i = 0; i <= n; i++) {
        if (i > 0) putchar(' ');
        printf("%d", a[i]);
    }
    putchar('\n');
    free(a);
    return 0;
}

code.C++:
#include <iostream>
#include <vector>
using namespace std;
int main() {
    int n; if (cin >> n) {
        vector<int> a(n);
        for (int i = 0; i < n; i++) cin >> a[i];
        int val, pos; cin >> val >> pos;
        a.insert(a.begin() + pos, val);
        for (size_t i = 0; i < a.size(); i++) {
            if (i > 0) cout << " ";
            cout << a[i];
        }
        cout << "\n";
    }
    return 0;
}

code.Java:
import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            List<Integer> a = new ArrayList<>();
            for (int i = 0; i < n; i++) a.add(sc.nextInt());
            int val = sc.nextInt(), pos = sc.nextInt();
            a.add(pos, val);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < a.size(); i++) {
                if (i > 0) sb.append(" ");
                sb.append(a.get(i));
            }
            System.out.println(sb.toString());
        }
    }
}

